      "path": "src/hosts/deepseek-harness/guard.ts",
      "content": "import { randomUUID } from 'node:crypto';\nimport { resolve } from 'node:path';\nimport { formatDenial } from '@/core/denial';\nimport { createProcessEnvironment, type PathResolver } from '@/core/environment';\nimport { loadPolicySnapshot } from '@/core/policy/snapshot';\nimport { getNonCommandToolInputKind } from '@/core/tool-input';\nimport { firstTrustedRoot } from '@/gate/intake';\nimport { getDeepSeekHarnessProfilesDir } from '@/hosts/deepseek-harness/detect';\nimport { type CommandToolKind, createToolInvocation, type ToolInvocation } from '@/gate/invocation';\nimport {\n  createPluginToolCallHandler,\n  failedClosedToolCall,\n  type MalformedToolCall,\n  malformedToolCall,\n  type PluginHandlerOptions,\n  type PluginToolCallHost,\n  refusedCwdToolCall,\n} from '@/hosts/hook/plugin-adapter';\n\ntype DeepSeekHarnessToolExecution = {\n  name: unknown;\n  arguments: unknown;\n  agent?: { session: { header: { id: string; cwd: string } } };\n};\n\ntype DeepSeekHarnessToolGuard = (execution: unknown) => string | undefined;\n\ntype DeepSeekHarnessPostToolDecision = {\n  kind: 'accept' | 'block';\n  additionalContexts?: unknown[];\n};\n\ntype DeepSeekHarnessPostExecuteListener = (\n  execution: unknown,\n  result: unknown,\n  next: () => Promise<DeepSeekHarnessPostToolDecision>,\n) => Promise<DeepSeekHarnessPostToolDecision>;\n\ntype DeepSeekHarnessContext = {\n  tools: { guard: (guard: DeepSeekHarnessToolGuard) => () => void };\n  on: (event: 'tools/post-execute', listener: DeepSeekHarnessPostExecuteListener) => () => void;\n};\n\nexport const DEEPSEEK_HARNESS_COMMAND_TOOLS = new Map<string, CommandToolKind>([\n  ['bash', 'posix'],\n  ['pwsh', 'powershell'],\n]);\n\nconst DEEPSEEK_HARNESS_HOST: PluginToolCallHost<unknown, string, string | undefined> = {\n  agent: 'deepseek-harness',\n  debugLabel: 'deepseek-harness tool guard',\n  extract: (execution, launchCwd, paths) => getDeepSeekHarnessToolCall(execution, launchCwd, paths),\n  getSessionId: (execution) =>\n    (execution as DeepSeekHarnessToolExecution | null)?.agent?.session.header.id,\n  allow: undefined,\n  block: (denial) => formatDenial(denial),\n  includeEvidenceOnError: (toolCall) => toolCall.route.kind === 'command',\n};\n\nexport function registerDeepSeekHarnessGuard(ctx: DeepSeekHarnessContext): void {\n  const handle = createDeepSeekHarnessGuardHandler();\n  ctx.tools.guard((execution) => handle(execution, process.cwd()));\n  const noticed = new Set<string>();\n  ctx.on('tools/post-execute', async (execution, _result, next) => {\n    const decision = await next();\n    const notice = noticeUndeclaredCommandTool(execution, noticed);\n    if (!notice) return decision;\n    return { ...decision, additionalContexts: [notice, ...(decision.additionalContexts ?? [])] };\n  });\n}\n\nfunction noticeUndeclaredCommandTool(execution: unknown, noticed: Set<string>) {\n  try {\n    const toolCall = execution as DeepSeekHarnessToolExecution | null;\n    const header = toolCall?.agent?.session.header;\n    const toolName = toolCall?.name;\n    const input = toolCall?.arguments;\n    const command = (input as { command?: unknown } | null | undefined)?.command;\n    if (\n      !header ||\n      typeof toolName !== 'string' ||\n      DEEPSEEK_HARNESS_COMMAND_TOOLS.has(toolName) ||\n      getNonCommandToolInputKind(toolName) !== 'unknown' ||\n      typeof command !== 'string' ||\n      command.trim() === ''\n    ) {\n      return undefined;\n    }\n    const key = JSON.stringify([header.id, toolName]);\n    if (noticed.has(key)) return undefined;\n    const environment = createProcessEnvironment();\n    const declared = loadPolicySnapshot(environment, {\n      cwd: header.cwd ?? process.cwd(),\n    }).policy.commandTools.some((tool) => tool.name === toolName);\n    if (declared) return undefined;\n    noticed.add(key);\n    const profilesDir = getDeepSeekHarnessProfilesDir(environment);\n    return Object.freeze({\n      id: randomUUID(),\n      role: 'user',\n      content: Object.freeze([\n        Object.freeze({\n          type: 'text',\n          text: `CC Safety Net did not check the command \\`${toolName}\\` just ran. It checks a plugin's shell tool only after the tool is declared. First find out where \\`${toolName}\\` runs its commands: check its tool description, and if that doesn't say, read its plugin's source under \\`${profilesDir}/<profile>/node_modules\\`. If it runs them on this machine, declare it with \\`npx -y cc-safety-net rule tool add ${toolName}\\`, and add \\`--cwd-arg <name>\\` if it takes its working directory in an argument other than \\`workdir\\`, \\`cwd\\` or \\`working_directory\\`. If it runs them somewhere else, such as a remote host, or you can't tell, declare it with \\`npx -y cc-safety-net rule tool add ${toolName} --no-cwd-arg\\`: its commands are then checked as if they ran in this session's directory. Don't test the declaration by running a destructive command; \\`npx -y cc-safety-net rule tool list\\` confirms it. Either way, tell the user what you found and what you did.`,\n        }),\n      ]),\n      source: Object.freeze({\n        kind: 'cc-safety-net',\n        form: 'notice',\n        summary: `${toolName} commands are not checked`,\n      }),\n    });\n  } catch {\n    return undefined;\n  }\n}\n\n/** @internal */\nexport function createDeepSeekHarnessGuardHandler(\n  options: PluginHandlerOptions = {},\n): (execution: unknown, launchCwd: string) => string | undefined {\n  return createPluginToolCallHandler(DEEPSEEK_HARNESS_HOST, options);\n}\n\nfunction getDeepSeekHarnessToolCall(\n  execution: unknown,\n  launchCwd: string,\n  paths: PathResolver,\n): MalformedToolCall | ToolInvocation {\n  if (!execution || typeof execution !== 'object') return failedClosedToolCall(null);\n  const toolCall = execution as DeepSeekHarnessToolExecution;\n  const sessionCwd = toolCall.agent?.session.header.cwd ?? launchCwd;\n  const workspace = firstTrustedRoot([sessionCwd], paths);\n  const toolName = toolCall.name;\n  if (typeof toolName !== 'string' || toolName.trim() === '') {\n    return malformedToolCall(workspace ?? null);\n  }\n  if (!workspace) {\n    return refusedCwdToolCall(\n      { directory: 'session', problem: 'unusable', cwd: sessionCwd },\n      { toolName },\n    );\n  }\n\n  const input = toolCall.arguments;\n  const shell = DEEPSEEK_HARNESS_COMMAND_TOOLS.get(toolName);\n  if (!shell) {\n    return createToolInvocation(\n      toolName,\n      input,\n      { kind: getNonCommandToolInputKind(toolName) },\n      { configCwd: workspace, executionCwd: workspace },\n      null,\n    );\n  }\n\n  if (!input || typeof input !== 'object' || Array.isArray(input)) {\n    return malformedToolCall(workspace, { toolName });\n  }\n  const shellInput = input as Record<string, unknown>;\n  const command = shellInput.command;\n  if (typeof command !== 'string' || command.trim() === '') {\n    return malformedToolCall(workspace, { toolName });\n  }\n\n  const workdir = shellInput.workdir;\n  if (workdir !== undefined && (typeof workdir !== 'string' || workdir.trim() === '')) {\n    return malformedToolCall(workspace, { command, toolName });\n  }\n  const executionCwd =\n    workdir === undefined ? workspace : firstTrustedRoot([resolve(workspace, workdir)], paths);\n  if (!executionCwd) {\n    return refusedCwdToolCall(\n      { directory: 'requested', problem: 'unusable', cwd: workdir as string },\n      { command, toolName },\n    );\n  }\n\n  return createToolInvocation(\n    toolName,\n    input,\n    { kind: 'command', shell },\n    { configCwd: workspace, executionCwd },\n    command,\n  );\n}\n"
    },
    {
      "path": "src/core/denial.ts",
      "content": "import { REASON_SAFETY_NET_FAILED_CLOSED } from './budget';\nimport type { BlockIntent, Decision } from './decision';\nimport { redactSecrets } from './redaction';\n\n/** @internal */\nexport interface FormatBlockedMessageInput {\n  reason: string;\n  ruleId?: string;\n  intent?: BlockIntent;\n  command?: string;\n  segment?: string;\n  toolName?: string;\n  cwd?: string;\n  maxLen?: number;\n  redact?: (text: string) => string;\n  configWarning?: string;\n  askUser?: boolean;\n}\n\nconst FOOTERS: Record<BlockIntent, string> = {\n  hard_stop:\n    'Do not retry this operation or attempt any workaround (other tools, flags, or paths). Report the block to the user and continue with the rest of the task.',\n  use_alternative:\n    'Do not retry the blocked form. Continue the task using the safer alternative described above.',\n  scope_down:\n    'Retry with a narrower, explicit target as described above. Escalate to the user if the broad operation is truly required.',\n  manual_only:\n    'If this operation is truly needed, ask the user for explicit permission and have them run the command manually.',\n  stop_and_explain:\n    'Do not brute-force variants. Simplify or restructure the command so it can be analyzed, or report the block to the user.',\n};\n\n/** @internal */\nexport function formatBlockedMessage(input: FormatBlockedMessageInput): string {\n  const maxLen = input.maxLen ?? 200;\n  const redact = input.redact ?? ((text: string) => text);\n  const excerpt = (text: string) => (text.length > maxLen ? `${text.slice(0, maxLen)}...` : text);\n\n  return [\n    input.askUser ? 'CC Safety Net could not verify this command' : 'BLOCKED by CC Safety Net',\n    `Reason: ${redact(input.reason)}`,\n    input.ruleId ? `Rule: ${input.ruleId}` : undefined,\n    input.toolName ? `Tool: ${input.toolName}` : undefined,\n    input.command ? `Command: ${excerpt(redact(input.command))}` : undefined,\n    input.segment && input.segment !== input.command\n      ? `Segment: ${excerpt(redact(input.segment))}`\n      : undefined,\n    input.cwd ? `Working directory: ${excerpt(redact(input.cwd))}` : undefined,\n    input.configWarning ? `Config warning: ${redact(input.configWarning)}` : undefined,\n    input.askUser\n      ? 'Approve only if you expected this command.'\n      : FOOTERS[input.intent ?? 'manual_only'],\n  ]\n    .filter((line): line is string => line !== undefined)\n    .join('\\n\\n');\n}\n\nexport type IntegrationDenial = {\n  reason: string;\n  ruleId?: string;\n  intent?: BlockIntent;\n  command?: string;\n  segment?: string;\n  toolName?: string;\n  cwd?: string;\n\n  configWarning?: string;\n  unverifiedByStandardMode?: true;\n};\n\nexport function projectGuardDenial(\n  evaluation: { decision: Decision; configFallback?: { reason: string } },\n  options: { includeEvidence: boolean; toolName?: string },\n): IntegrationDenial | undefined {\n  if (evaluation.decision.kind !== 'deny') return undefined;\n  const evidence = options.includeEvidence ? evaluation.decision.evidence : undefined;\n  return {\n    reason: evaluation.decision.reason,\n    ruleId: evaluation.decision.ruleId,\n    intent: evaluation.decision.intent,\n    command: evidence?.command,\n    segment: evidence?.segment,\n    toolName: options.toolName,\n\n    ...(evaluation.configFallback ? { configWarning: evaluation.configFallback.reason } : {}),\n    ...(evaluation.decision.unverifiedByStandardMode\n      ? { unverifiedByStandardMode: true as const }\n      : {}),\n  };\n}\n\nexport function createFailedClosedDenial(\n  options: Pick<IntegrationDenial, 'command' | 'segment' | 'toolName'> = {},\n): IntegrationDenial {\n  return {\n    reason: REASON_SAFETY_NET_FAILED_CLOSED,\n    ruleId: 'analysis.failed-closed',\n    intent: 'stop_and_explain',\n    command: options.command,\n    segment: options.segment ?? options.command,\n    toolName: options.toolName,\n  };\n}\n\nexport function createMalformedToolCallDenial(\n  options: Pick<IntegrationDenial, 'command' | 'toolName'> = {},\n) {\n  return {\n    reason:\n      'CC Safety Net could not check this tool call because it arrived without a usable tool name or arguments. This is not a CC Safety Net failure. Send the call again with its tool name and complete arguments.',\n    ruleId: 'tool-call.malformed',\n    intent: 'use_alternative',\n    command: options.command,\n    segment: options.command,\n    toolName: options.toolName,\n  } satisfies IntegrationDenial;\n}\n\nconst CWD_DENIALS = {\n  session: {\n    unusable: {\n      reason:\n        \"CC Safety Net cannot check tool calls because the session's working directory or workspace root no longer exists, is inaccessible, is not a directory, or uses an unsupported path form. Ask the user to restart the session from an existing directory.\",\n      intent: 'hard_stop',\n      ruleId: 'cwd.session-unusable',\n    },\n    'outside-workspace': {\n      reason:\n        \"CC Safety Net cannot check tool calls because the session's working directory is outside its workspace roots. Ask the user to restart the session from a directory inside the workspace.\",\n      intent: 'hard_stop',\n      ruleId: 'cwd.session-outside-workspace',\n    },\n  },\n  requested: {\n    unusable: {\n      reason:\n        'CC Safety Net could not use the requested working directory because it does not exist, is inaccessible, is not a directory, or uses an unsupported path form. Use an existing accessible working directory. If the requested directory is missing, create it from an accessible location before retrying the command.',\n      intent: 'use_alternative',\n      ruleId: 'cwd.requested-unusable',\n    },\n    'outside-workspace': {\n      reason:\n        \"CC Safety Net could not use the requested working directory because it is outside the session's workspace. Use a working directory inside the workspace.\",\n      intent: 'use_alternative',\n      ruleId: 'cwd.requested-outside-workspace',\n    },\n  },\n} as const satisfies Record<\n  string,\n  Record<string, { reason: string; intent: BlockIntent; ruleId: string }>\n>;\n\nexport type CwdProblem = keyof (typeof CWD_DENIALS)['session'];\n\nexport type CwdDenial = {\n  directory: keyof typeof CWD_DENIALS;\n  problem: CwdProblem;\n  cwd: string;\n};\n\nexport function createCwdDenial(\n  cause: CwdDenial,\n  options: Pick<IntegrationDenial, 'command' | 'toolName'> = {},\n) {\n  return {\n    ...CWD_DENIALS[cause.directory][cause.problem],\n    command: options.command,\n    toolName: options.toolName,\n    cwd: cause.cwd,\n  };\n}\n\nexport function formatDenial(denial: IntegrationDenial): string {\n  return formatBlockedMessage({ ...denial, redact: redactSecrets });\n}\n\nexport function formatAskPrompt(denial: IntegrationDenial): string {\n  return formatBlockedMessage({ ...denial, redact: redactSecrets, askUser: true });\n}\n\nexport function formatIntegrationError(cause: unknown): string {\n  return redactSecrets(cause instanceof Error ? cause.message : String(cause));\n}\n"
    },
    {
      "path": "src/entries/deepseek-harness/index.ts",
      "content": "import { registerDeepSeekHarnessGuard } from '@/hosts/deepseek-harness/guard';\n\nexport default {\n  name: 'cc-safety-net',\n  inject: ['tools'],\n  apply: registerDeepSeekHarnessGuard,\n};\n"
    },
    {
      "path": "src/hosts/hook/plugin-adapter.ts",
      "content": "import {\n  type CwdDenial,\n  createCwdDenial,\n  createFailedClosedDenial,\n  createMalformedToolCallDenial,\n  formatIntegrationError,\n  type IntegrationDenial,\n  projectGuardDenial,\n} from '@/core/denial';\nimport { createProcessEnvironment, type PathResolver } from '@/core/environment';\nimport { ENV_FLAGS, envTruthy, shouldRecordAllowedCommands } from '@/core/policy/env';\nimport type { PolicySnapshotOptions } from '@/core/policy/snapshot';\nimport type { ToolInvocation } from '@/gate/invocation';\nimport { type GuardDependencies, GuardEvaluationError } from '@/gate/pipeline';\nimport { writeIntegrationDenialAudit } from '@/hosts/audit';\nimport { evaluateRuntimeGuard } from '@/hosts/runtime';\n\nexport type MalformedToolCall = {\n  malformed: true;\n  denial: IntegrationDenial;\n  cwd: string | null;\n};\n\nexport type PluginHandlerOptions = {\n  guardDependencies?: Partial<GuardDependencies>;\n  policyOptions?: Omit<PolicySnapshotOptions, 'cwd'>;\n};\n\nexport type PluginToolCallHost<Event, Context, Result> = {\n  agent: string;\n  debugLabel: string;\n  extract: (\n    event: Event,\n    ctx: Context,\n    paths: PathResolver,\n  ) => MalformedToolCall | ToolInvocation | undefined;\n  getSessionId: (event: Event, ctx: Context) => string | undefined;\n  allow: Result;\n  block: (denial: IntegrationDenial) => Result;\n  includeEvidenceOnError: (toolCall: ToolInvocation) => boolean;\n  cancelled?: (ctx: Context) => boolean;\n};\n\nexport function malformedToolCall(\n  cwd: string | null,\n  denial: Pick<IntegrationDenial, 'command' | 'toolName'> = {},\n): MalformedToolCall {\n  return { malformed: true, denial: createMalformedToolCallDenial(denial), cwd };\n}\n\nexport function failedClosedToolCall(\n  cwd: string | null,\n  denial: Pick<IntegrationDenial, 'command' | 'toolName'> = {},\n): MalformedToolCall {\n  return { malformed: true, denial: createFailedClosedDenial(denial), cwd };\n}\n\nexport function refusedCwdToolCall(\n  cause: CwdDenial,\n  denial: Pick<IntegrationDenial, 'command' | 'toolName'>,\n): MalformedToolCall {\n  return { malformed: true, denial: createCwdDenial(cause, denial), cwd: cause.cwd };\n}\n\nexport function createPluginToolCallHandler<Event, Context, Result>(\n  host: PluginToolCallHost<Event, Context, Result>,\n  options: PluginHandlerOptions = {},\n): (event: Event, ctx: Context) => Result {\n  return (event, ctx) => {\n    try {\n      return handlePluginToolCall(event, ctx, host, options);\n    } catch (error) {\n      console.error('CC Safety Net error:', error);\n      return host.block(createFailedClosedDenial());\n    }\n  };\n}\n\nfunction handlePluginToolCall<Event, Context, Result>(\n  event: Event,\n  ctx: Context,\n  host: PluginToolCallHost<Event, Context, Result>,\n  options: PluginHandlerOptions,\n): Result {\n  const environment = createProcessEnvironment();\n  if (host.cancelled?.(ctx)) return host.block(createFailedClosedDenial());\n\n  const toolCall = host.extract(event, ctx, environment.paths);\n  if (!toolCall) return host.allow;\n\n  const getSessionId = () => host.getSessionId(event, ctx);\n  if ('malformed' in toolCall) {\n    writeIntegrationDenialAudit(environment, toolCall.denial, getSessionId, {\n      agent: host.agent,\n      toolName: toolCall.denial.toolName,\n      cwd: toolCall.cwd,\n    });\n    return host.block(toolCall.denial);\n  }\n\n  const project = (\n    evaluation: Parameters<typeof projectGuardDenial>[0],\n    includeEvidence: boolean,\n  ) => {\n    const denial = projectGuardDenial(evaluation, { includeEvidence });\n    return denial ? host.block(denial) : host.allow;\n  };\n\n  try {\n    const evaluation = evaluateRuntimeGuard(environment, toolCall, {\n      guard: {\n        auditAllowed: shouldRecordAllowedCommands(environment.env),\n        policyOptions: options.policyOptions,\n        dependencies: options.guardDependencies,\n      },\n      audit: { agent: host.agent, getSessionId },\n    });\n    return project(evaluation, true);\n  } catch (error) {\n    if (!(error instanceof GuardEvaluationError)) throw error;\n    if (envTruthy(ENV_FLAGS.debug, environment.env)) {\n      console.error(\n        `CC Safety Net debug: ${host.debugLabel} analysis failed: ${formatIntegrationError(error.cause)}`,\n      );\n    }\n    return project(error.evaluation, host.includeEvidenceOnError(toolCall));\n  }\n}\n"
    },
    {
      "path": "src/hosts/runtime.ts",
      "content": "import type { AuditErrorCode, AuditFailureStage } from '@/core/audit';\nimport { AnalysisLimit, LIMITS } from '@/core/budget';\nimport type { Environment } from '@/core/environment';\nimport { ToolInputLimitError } from '@/core/tool-input';\nimport {\n  StructuralShellSyntaxLimitError,\n  UnparseableCommandError,\n} from '@/gate/guards/semantic-facts';\nimport type { ToolInvocation } from '@/gate/invocation';\nimport {\n  evaluateGuard,\n  type GuardEvaluation,\n  GuardEvaluationError,\n  type GuardOptions,\n} from '@/gate/pipeline';\nimport { projectGuardAudit, writeGuardAudit } from './audit';\n\ntype RuntimeAuditOptions = {\n  agent: string;\n  shape?: string;\n  getSessionId: () => string | undefined;\n};\n\nexport function evaluateRuntimeGuard(\n  environment: Environment,\n  invocation: ToolInvocation,\n  options: { guard?: Omit<GuardOptions, 'environment'>; audit: RuntimeAuditOptions },\n) {\n  try {\n    const evaluation = evaluateGuard(invocation, { environment, ...options.guard });\n    writeRuntimeAudit(environment, invocation, evaluation, options);\n    return evaluation;\n  } catch (error) {\n    if (!(error instanceof GuardEvaluationError)) throw error;\n    writeRuntimeAudit(\n      environment,\n      invocation,\n      error.evaluation,\n      options,\n      !(error.cause instanceof ToolInputLimitError),\n      { stage: error.stage, errorCode: classifyAuditError(error.cause) },\n    );\n    throw error;\n  }\n}\n\nfunction writeRuntimeAudit(\n  environment: Environment,\n  invocation: ToolInvocation,\n  evaluation: GuardEvaluation,\n  options: { guard?: Omit<GuardOptions, 'environment'>; audit: RuntimeAuditOptions },\n  includeInvocationCommand = true,\n  failure?: { stage: AuditFailureStage; errorCode: AuditErrorCode },\n): void {\n  writeGuardAudit(\n    environment,\n    projectGuardAudit(\n      evaluation.promotedInvocation ?? invocation,\n      evaluation,\n      options.guard?.auditAllowed ?? false,\n      includeInvocationCommand,\n      failure,\n    ),\n    options.audit.getSessionId,\n    {\n      agent: options.audit.agent,\n      shape: options.audit.shape,\n    },\n  );\n}\n\nfunction classifyAuditError(cause: unknown): AuditErrorCode {\n  if (cause instanceof AnalysisLimit) return LIMITS[cause.kind].errorCode;\n  if (cause instanceof ToolInputLimitError) return 'tool-input-limit';\n  if (cause instanceof StructuralShellSyntaxLimitError) return 'structural-shell-syntax-limit';\n  if (cause instanceof UnparseableCommandError) return 'unparseable-command';\n  return 'unexpected-error';\n}\n"
    },
    {
      "path": "src/gate/pipeline.ts",
      "content": "import type { AuditFailureStage } from '@/core/audit';\nimport { type AnalysisErrorCode, AnalysisLimit, createBudget } from '@/core/budget';\nimport type { Decision } from '@/core/decision';\nimport { createCwdDenial, createMalformedToolCallDenial } from '@/core/denial';\nimport type { PathResolver } from '@/core/environment';\nimport type { ProtectedGitMetadata } from '@/core/git/metadata';\nimport { getCCSafetyNetEnvModes } from '@/core/policy/env';\nimport { loadPolicySnapshot, type PolicySnapshotOptions } from '@/core/policy/snapshot';\nimport type { EffectiveSafetyLevel, PolicySnapshot } from '@/core/policy/types';\nimport { getCommandFromToolInput, ToolInputLimitError } from '@/core/tool-input';\nimport type { AnalyzeInput, EnvironmentContext } from '@/gate/analysis';\nimport { analyzeCommandWithProgram, analyzeOrCapBreach } from '@/gate/analyzer';\nimport { dangerousInTextMatch } from '@/gate/analyzer/dangerous-text';\nimport { REASON_DYNAMIC_SHELL_SOURCE } from '@/gate/analyzer/reasons';\nimport {\n  REASON_COMMAND_ANALYSIS_LIMIT,\n  REASON_RECURSION_LIMIT,\n  REASON_SAFETY_NET_FAILED_CLOSED,\n  REASON_STRICT_UNPARSEABLE,\n  REASON_STRUCTURAL_COMMAND_VALIDATION_LIMIT,\n} from '@/gate/analyzer/reasons';\nimport type { SemanticFacts } from '@/gate/facts';\nimport {\n  findGitMetadataMutationTargetInSemanticFacts,\n  REASON_GIT_METADATA_PROTECTION,\n} from '@/gate/guards/git-metadata-protection';\nimport {\n  findPolicyApplyInvocationInSemanticFacts,\n  REASON_POLICY_APPLY_PROTECTION,\n} from '@/gate/guards/policy-apply-protection';\nimport {\n  findPolicyConfigMutationTargetInSemanticFacts,\n  REASON_POLICY_CONFIG_PROTECTION,\n} from '@/gate/guards/policy-protection';\nimport {\n  createSemanticFacts,\n  getCommandSyntaxFact,\n  StructuralShellSyntaxLimitError,\n  UnparseableCommandError,\n} from '@/gate/guards/semantic-facts';\nimport { resolveCanonicalCwd } from '@/gate/intake';\nimport { createToolInvocation, type ToolInvocation } from '@/gate/invocation';\nimport {\n  findSensitiveTargetInSemanticFacts,\n  REASON_SECRET_PROTECTION,\n} from '@/gate/secret/secret-protection';\nimport type { CommandTraceContext } from '@/gate/trace';\n\nexport type GuardStage = AuditFailureStage;\n\nexport type GuardEvaluation = {\n  stage: GuardStage;\n  decision: Decision;\n\n  promotedInvocation?: ToolInvocation;\n\n  level?: EffectiveSafetyLevel;\n\n  configFallback?: { reason: string };\n\n  errorCode?: AnalysisErrorCode;\n};\n\nexport type GuardDependencies = {\n  findPolicyMutation: typeof findPolicyConfigMutationTargetInSemanticFacts;\n  findGitMetadataMutation: typeof findGitMetadataMutationTargetInSemanticFacts;\n  loadPolicySnapshot: typeof loadPolicySnapshot;\n  findSensitiveTarget: typeof findSensitiveTargetInSemanticFacts;\n  analyzeCommand: (\n    command: string,\n    options: AnalyzeInput,\n    program?: ReturnType<typeof getDeclaredCommandProgram>,\n    factStore?: SemanticFacts['store'],\n  ) => Extract<Decision, { kind: 'deny' }> | null;\n  resolveGitMetadata: typeof resolveGitMetadataForCwds;\n  getModes: typeof getCCSafetyNetEnvModes;\n};\n\nexport type GuardOptions = {\n  environment: EnvironmentContext;\n  auditAllowed?: boolean;\n  policyOptions?: Omit<PolicySnapshotOptions, 'cwd'>;\n  dependencies?: Partial<GuardDependencies>;\n\n  trace?: CommandTraceContext;\n};\n\nexport class GuardEvaluationError extends Error {\n  override readonly name = 'GuardEvaluationError';\n\n  constructor(\n    readonly stage: GuardStage,\n    readonly evaluation: GuardEvaluation,\n    cause: unknown,\n  ) {\n    super(`CC Safety Net ${stage} dependency failed`, { cause });\n  }\n}\n\nconst DEFAULT_DEPENDENCIES: GuardDependencies = {\n  findPolicyMutation: findPolicyConfigMutationTargetInSemanticFacts,\n  findGitMetadataMutation: findGitMetadataMutationTargetInSemanticFacts,\n  resolveGitMetadata: resolveGitMetadataForCwds,\n  loadPolicySnapshot,\n  findSensitiveTarget: findSensitiveTargetInSemanticFacts,\n  analyzeCommand: analyzeCommandWithProgram,\n  getModes: getCCSafetyNetEnvModes,\n};\n\nconst BARE_SHELL_READING_STDIN = /^(?:\\S*\\/)?(?:ba|da|z|k)?sh(?:\\s+-[A-Za-z-]*)*$/;\nconst WORKING_DIRECTORY_ARGUMENTS = ['workdir', 'cwd', 'working_directory'];\n\nexport function evaluateGuard(\n  hostInvocation: ToolInvocation,\n  options: GuardOptions,\n): GuardEvaluation {\n  const dependencies = { ...DEFAULT_DEPENDENCIES, ...options.dependencies };\n  const inputCommand = getInputCommandOrFail(hostInvocation);\n  const loadSnapshot = () =>\n    callDependency('config-load', inputCommand, () =>\n      dependencies.loadPolicySnapshot(options.environment, {\n        ...options.policyOptions,\n        cwd: hostInvocation.context.configCwd,\n      }),\n    );\n  const declarationSnapshot =\n    hostInvocation.route.kind === 'unknown' && inputCommand ? loadSnapshot() : undefined;\n  const declaration = declarationSnapshot?.policy.commandTools.find(\n    (tool) => tool.name === hostInvocation.toolName,\n  );\n  const promotion =\n    declaration && inputCommand\n      ? promoteDeclaredCommandTool(\n          hostInvocation,\n          inputCommand,\n          declaration.cwd,\n          options.environment.paths,\n        )\n      : hostInvocation;\n  if ('decision' in promotion) return promotion;\n  const invocation = promotion;\n  const promoted = invocation === hostInvocation ? {} : { promotedInvocation: invocation };\n  const command = isCommandInvocation(invocation) ? invocation.command : inputCommand;\n\n  const facts = callDependency('policy-protection', command, () => createSemanticFacts(invocation));\n  const inputCandidate = getCommandSyntaxFact(facts, 'input-candidate');\n  const declaredCommand = getCommandSyntaxFact(facts, 'declared-command');\n  if (\n    isCommandInvocation(invocation) &&\n    invocation.command?.trim() &&\n    declaredCommand?.program.status === 'limited'\n  ) {\n    return {\n      stage: 'command-analysis',\n      ...promoted,\n      decision: {\n        kind: 'deny',\n        reason: REASON_RECURSION_LIMIT,\n        ruleId: 'analysis.recursion-limit',\n        intent: 'stop_and_explain',\n        evidence: { command: invocation.command, segment: invocation.command },\n      },\n    };\n  }\n  if (inputCandidate?.program.status === 'limited') {\n    return {\n      stage: 'command-validation',\n      ...promoted,\n      decision: {\n        kind: 'deny',\n        reason: REASON_STRUCTURAL_COMMAND_VALIDATION_LIMIT,\n        ruleId: 'analysis.structural-limit',\n        intent: 'stop_and_explain',\n      },\n    };\n  }\n\n  const budget = createBudget();\n  const protectedGitMetadata = callDependency('policy-protection', command, () =>\n    dependencies.resolveGitMetadata(\n      [invocation.context.executionCwd, invocation.context.configCwd],\n      options.environment,\n    ),\n  );\n  const policyTarget = callDependency('policy-protection', command, () =>\n    dependencies.findPolicyMutation(facts, options.environment, budget),\n  );\n  if (policyTarget) {\n    const displayCommand = command ?? policyTarget.target;\n    return {\n      stage: 'policy-protection',\n      ...promoted,\n      decision: {\n        kind: 'deny',\n        reason: REASON_POLICY_CONFIG_PROTECTION,\n        ruleId: 'guard.policy-config',\n        intent: 'hard_stop',\n        evidence: { command: displayCommand, segment: policyTarget.target },\n      },\n    };\n  }\n\n  const policyApplyTarget = callDependency('policy-protection', command, () =>\n    findPolicyApplyInvocationInSemanticFacts(facts, options.environment, budget),\n  );\n  if (policyApplyTarget) {\n    const displayCommand = command ?? policyApplyTarget.target;\n    return {\n      stage: 'policy-protection',\n      ...promoted,\n      decision: {\n        kind: 'deny',\n        reason: REASON_POLICY_APPLY_PROTECTION,\n        ruleId: 'guard.policy-apply',\n        intent: 'hard_stop',\n        evidence: { command: displayCommand, segment: policyApplyTarget.target },\n      },\n    };\n  }\n\n  const gitMetadataTarget = callDependency('policy-protection', command, () =>\n    dependencies.findGitMetadataMutation(facts, protectedGitMetadata, options.environment, budget),\n  );\n  if (gitMetadataTarget) {\n    const displayCommand = command ?? gitMetadataTarget.target;\n    return {\n      stage: 'policy-protection',\n      ...promoted,\n      decision: {\n        kind: 'deny',\n        reason: REASON_GIT_METADATA_PROTECTION,\n        ruleId: 'guard.git-metadata',\n        intent: 'hard_stop',\n        evidence: { command: displayCommand, segment: gitMetadataTarget.target },\n      },\n    };\n  }\n\n  const snapshot = declarationSnapshot ?? loadSnapshot();\n  const policy = snapshot.policy;\n  const modes = dependencies.getModes(policy, options.environment.env);\n\n  const reported = {\n    level: modes.effectiveLevel,\n    ...getConfigFallback(snapshot),\n    ...promoted,\n  };\n  const secretTarget =\n    policy.secretProtection.enabled === false\n      ? null\n      : callDependency('secret-protection', command, () =>\n          dependencies.findSensitiveTarget(\n            policy.heredocDataWrappers.length === 0\n              ? facts\n              : createSemanticFacts(invocation, policy.heredocDataWrappers),\n            policy.secretProtection,\n            options.environment,\n            budget,\n            {\n              strict:\n                isCommandInvocation(invocation) || inputCandidate?.program.dialect === 'powershell'\n                  ? modes.strict\n                  : undefined,\n            },\n          ),\n        );\n  if (secretTarget) {\n    const displayCommand = command ?? secretTarget.target;\n    return {\n      stage: 'secret-protection',\n      ...reported,\n      decision: {\n        kind: 'deny',\n        reason: REASON_SECRET_PROTECTION,\n        intent: 'hard_stop',\n        ruleId: secretTarget.ruleId,\n        evidence: { command: displayCommand, segment: secretTarget.target },\n      },\n    };\n  }\n\n  if (!isCommandInvocation(invocation)) {\n    return { stage: 'non-command', ...reported, decision: { kind: 'allow' } };\n  }\n\n  if (!invocation.command || invocation.command.trim() === '') {\n    return { ...malformedToolCallEvaluation(command), ...reported };\n  }\n\n  const analysis = callDependency('command-analysis', command, () =>\n    analyzeOrCapBreach(\n      () =>\n        dependencies.analyzeCommand(\n          invocation.command as string,\n          {\n            cwd: invocation.context.configCwd,\n            effectiveCwd: invocation.context.executionCwd,\n            shell: invocation.route.shell,\n            policySnapshot: snapshot,\n            environment: options.environment,\n            protectedGitMetadata,\n            effectiveCapabilities: modes.capabilities,\n            worktreeMode: modes.worktreeMode,\n            budget,\n\n            ...(options.trace ? { trace: options.trace } : {}),\n          },\n          getDeclaredCommandProgram(facts),\n          facts.store,\n        ),\n      invocation.command as string,\n      options.trace,\n    ),\n  );\n  const readAsPosix =\n    invocation.route.shell === 'auto' && facts.store.readsAutoAsPowerShell()\n      ? () => {\n          const posixTrace = options.trace?.branch();\n          const evaluation: GuardEvaluation = {\n            ...evaluateGuard(\n              { ...invocation, route: { kind: 'command', shell: 'posix' } },\n              {\n                ...options,\n                ...(posixTrace ? { trace: posixTrace.trace } : {}),\n                dependencies: {\n                  ...options.dependencies,\n                  loadPolicySnapshot: () => snapshot,\n                  resolveGitMetadata: () => protectedGitMetadata,\n                },\n              },\n            ),\n            ...promoted,\n          };\n          return {\n            decision: evaluation.decision,\n            withItsTrace: () => {\n              posixTrace?.adopt();\n   